 65→func ReadJSON[T any](r io.Reader) (*T, error) {
 66→	var value T
 67→	if err := json.NewDecoder(r).Decode(&value); err != nil {
 68→		return nil, err
 69→	}
 70→	return &value, nil
 71→}
