 46→func (a *Agent) GetSessionID(input *protocol.HookInputJSON) string {
 47→	if input != nil && input.SessionID != "" {
 48→		return input.SessionID
 49→	}
 50→	return "stub-session-000"
 51→}
 52→
 53→func (a *Agent) ReadSession(input *protocol.HookInputJSON) (protocol.AgentSessionJSON, error) {
 54→	sessionID := a.GetSessionID(input)
 55→	repoRoot := protocol.RepoRoot()
 56→	sessionDir, err := a.GetSessionDir(repoRoot)
 57→	if err != nil {
 58→		return protocol.AgentSessionJSON{}, err
 59→	}
 60→	sessionRef := ""
 61→	if input != nil && input.SessionRef != "" {
 62→		sessionRef = input.SessionRef
 63→	} else {
 64→		sessionRef = a.ResolveSessionFile(sessionDir, sessionID)
 65→	}
 66→
 67→	var nativeData []byte
 68→	if sessionRef != "" {
 69→		data, err := os.ReadFile(sessionRef)
 70→		if err != nil {
 71→			return protocol.AgentSessionJSON{}, fmt.Errorf("failed to read transcript: %w", err)
 72→		}
 73→		nativeData = data
 74→	}
 75→
 76→	return protocol.AgentSessionJSON{
 77→		SessionID:     sessionID,
 78→		AgentName:     "kiro",
 79→		RepoPath:      repoRoot,
 80→		SessionRef:    sessionRef,
 81→		StartTime:     time.Now().UTC().Format(time.RFC3339),
 82→		NativeData:    nativeData,
 83→		ModifiedFiles: []string{},
 84→		NewFiles:      []string{},
 85→		DeletedFiles:  []string{},
 86→	}, nil
 87→}
 88→
 89→func (a *Agent) WriteSession(session protocol.AgentSessionJSON) error {
 90→	if session.SessionRef == "" {
 91→		return nil
 92→	}
 93→	if err := os.MkdirAll(filepath.Dir(session.SessionRef), 0o750); err != nil {
 94→		return err
 95→	}
 96→	return os.WriteFile(session.SessionRef, session.NativeData, 0o600)
 97→}
