308→func parseTranscript(data []byte) (*kiroTranscript, error) {
309→	if len(data) == 0 {
310→		return &kiroTranscript{}, nil
311→	}
312→
313→	var transcript kiroTranscript
314→	if err := json.Unmarshal(data, &transcript); err != nil {
315→		return nil, fmt.Errorf("failed to parse kiro transcript: %w", err)
316→	}
317→	if isCLITranscript(&transcript) {
318→		return &transcript, nil
319→	}
320→
321→	if converted := tryParseIDETranscript(data); converted != nil {
322→		return converted, nil
323→	}
324→
325→	return &transcript, nil
326→}
