328→func isCLITranscript(transcript *kiroTranscript) bool {
329→	if len(transcript.History) == 0 {
330→		return false
331→	}
332→	return len(transcript.History[0].User.Content) > 0 || len(transcript.History[0].Assistant) > 0
333→}
