335→func tryParseIDETranscript(data []byte) *kiroTranscript {
336→	var ide kiroIDETranscript
337→	if err := json.Unmarshal(data, &ide); err != nil {
338→		return nil
339→	}
340→	if len(ide.History) == 0 || ide.History[0].Message.Role == "" {
341→		return nil
342→	}
343→	return convertIDETranscript(&ide)
344→}
