346→func convertIDETranscript(ide *kiroIDETranscript) *kiroTranscript {
347→	transcript := &kiroTranscript{}
348→
349→	var pendingUser *kiroIDEHistoryEntry
350→	for i := range ide.History {
351→		entry := &ide.History[i]
352→		switch entry.Message.Role {
353→		case "user":
354→			if pendingUser != nil {
355→				transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, nil))
356→			}
357→			pendingUser = entry
358→		case "assistant":
359→			transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, entry))
360→			pendingUser = nil
361→		}
362→	}
363→
364→	if pendingUser != nil {
365→		transcript.History = append(transcript.History, ideEntryToPaired(pendingUser, nil))
366→	}
367→
368→	return transcript
369→}
