371→func ideEntryToPaired(user, assistant *kiroIDEHistoryEntry) kiroHistoryEntry {
372→	entry := kiroHistoryEntry{}
373→
374→	if user != nil {
375→		prompt := extractIDEUserText(user.Message.Content)
376→		if prompt != "" {
377→			content, err := json.Marshal(kiroPromptContent{
378→				Prompt: struct {
379→					Prompt string `json:"prompt"`
380→				}{Prompt: prompt},
381→			})
382→			if err == nil {
383→				entry.User.Content = content
384→			}
385→		} else {
386→			entry.User.Content = user.Message.Content
387→		}
388→	}
389→
390→	if assistant != nil {
391→		text := extractIDEAssistantText(assistant.Message.Content)
392→		if text != "" {
393→			content, err := json.Marshal(kiroResponseContent{
394→				Response: kiroResponsePayload{Content: text},
395→			})
396→			if err == nil {
397→				entry.Assistant = content
398→			}
399→		} else {
400→			entry.Assistant = assistant.Message.Content
401→		}
402→	}
403→
404→	return entry
405→}
