func TestKiro_Info(t *testing.T) {
	t.Parallel()
	env := NewKiroTestEnv(t)

	var resp struct {
		ProtocolVersion int      `json:"protocol_version"`
		Name            string   `json:"name"`
		Type            string   `json:"type"`
		Description     string   `json:"description"`
		IsPreview       bool     `json:"is_preview"`
